import ctypes,json,os,sys
from pathlib import Path
from datetime import datetime,timezone
def now():
    return datetime.now(timezone.utc).isoformat()
target=Path(sys.argv[1])
command=json.loads(sys.argv[2])
libc=ctypes.CDLL(None,use_errno=True)
result=libc.prctl(36,1,0,0,0)
if result != 0:
    raise OSError(ctypes.get_errno(),"PR_SET_CHILD_SUBREAPER")
probe=ctypes.c_int(0)
if libc.prctl(37,ctypes.byref(probe),0,0,0) != 0 or probe.value != 1:
    raise RuntimeError("PR_GET_CHILD_SUBREAPER verification failed")
record={"startedUtc":now(),"wrapperPid":os.getpid(),"subreaper":probe.value,"testCommand":command,"reaped":[]}
child=os.fork()
if child == 0:
    os.execv(command[0],command)
record["testPid"]=child
test_exit=None
while True:
    try:
        pid,status=os.waitpid(-1,0)
    except ChildProcessError:
        break
    code=os.waitstatus_to_exitcode(status)
    record["reaped"].append({"pid":pid,"rawWaitStatus":status,"exitCode":code,"isTestProcess":pid==child,"reapedUtc":now()})
    if pid == child:
        test_exit=code
record["testExit"]=test_exit
record["endedUtc"]=now()
record["allOwnChildrenReaped"]=True
target.write_text(json.dumps(record,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
if test_exit is None:
    raise SystemExit(125)
raise SystemExit(test_exit if test_exit >= 0 else 128-test_exit)
